-- D1 Schema & Data Dump for Yamaha Listings
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS listings (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  model TEXT NOT NULL DEFAULT 'Unknown',
  price INTEGER,
  currency TEXT NOT NULL DEFAULT 'PLN',
  location TEXT NOT NULL DEFAULT '',
  url TEXT NOT NULL,
  image TEXT,
  cc INTEGER NOT NULL DEFAULT 0,
  source TEXT NOT NULL DEFAULT 'Unknown',
  first_seen TEXT NOT NULL,
  last_seen TEXT NOT NULL,
  valid_until TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  iconic_blue INTEGER DEFAULT 0,
  iconic_blue_parts TEXT,
  iconic_blue_image TEXT,
  iconic_blue_checked_at TEXT,
  iconic_blue_verified INTEGER DEFAULT 0,
  iconic_blue_title TEXT,
  search_url TEXT
);

CREATE TABLE IF NOT EXISTS price_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  listing_id TEXT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  price INTEGER NOT NULL,
  recorded_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS scrape_runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  started_at TEXT NOT NULL,
  finished_at TEXT,
  total_found INTEGER NOT NULL DEFAULT 0,
  new_listings INTEGER NOT NULL DEFAULT 0,
  updated INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS idx_listings_is_active ON listings(is_active);
CREATE INDEX IF NOT EXISTS idx_listings_model ON listings(model);
CREATE INDEX IF NOT EXISTS idx_listings_source ON listings(source);
CREATE INDEX IF NOT EXISTS idx_listings_first_seen ON listings(first_seen);
CREATE INDEX IF NOT EXISTS idx_listings_cc ON listings(cc);
CREATE INDEX IF NOT EXISTS idx_price_hist_listing ON price_history(listing_id);

